'use client';

import { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import type { Project } from '@/lib/portfolio-data';

const claudeFigures = [{"src": "data:image/png;base64,", "alt": "Claude9 market intelligence: customer targeting, go-to-market strategy, engagement insights, and competitor gaps"}, {"src": "data:image/png;base64,", "alt": "Claude9 deployment concept using AWS, Docker, and Kubernetes"}, {"src": "data:image/png;base64,", "alt": "Claude9 optimization concept: data-driven revisions, measurement, and iteration"}, {"src": "data:image/png;base64,", "alt": "Future hardware workflow: describe, review, build"}, {"src": "data:image/png;base64,", "alt": "Claude9 five-year product roadmap"}];

const restartFigures = [{"src": "data:image/png;base64,", "alt": "Access Granted \u2014 Restart feature in Frisco Style"}, {"src": "data:image/png;base64,", "alt": "Frisco Nonprofit Founded by Teens is Giving Kids a Chance to ReStart \u2014 Lifestyle Frisco feature"}];

const communicationFigures = [{"src": "data:image/png;base64,", "caption": "Start a conversation"}, {"src": "data:image/png;base64,", "caption": "Record a silent phrase"}, {"src": "data:image/png;base64,", "caption": "Review the recording"}, {"src": "data:image/png;base64,", "caption": "Choose a suggested phrase"}, {"src": "data:image/png;base64,", "caption": "Edit and confirm the wording"}, {"src": "data:image/png;base64,", "caption": "Play it in your own voice"}, {"src": "data:image/png;base64,", "caption": "Share feedback"}, {"src": "data:image/png;base64,", "caption": "Revisit saved phrases"}, {"src": "data:image/png;base64,", "caption": "Set up a personal voice"}];

type ProjectModalProps = {
  project: Project | null;
  onClose: () => void;
};

export function ProjectModal({ project: sourceProject, onClose }: ProjectModalProps) {
  const project = sourceProject && /^claude\s*9$/i.test(sourceProject.title)
    ? {
        ...sourceProject,
        description: sourceProject.description.replace(/MBSA Case Competition/gi, 'Mosaic Case Competition'),
        process: sourceProject.process.replace(/MBSA Case Competition/gi, 'Mosaic Case Competition'),
        tags: sourceProject.tags?.map((tag) => tag.replace(/MBSA/gi, 'Mosaic')),
        links: [
          ...(sourceProject.links ?? []).filter((link) => !/deck/i.test(link.label)),
          { label: 'View full deck', href: 'https://www.figma.com/proto/nKxWurMXCINdBnZ4GyuGoo/Claude9-MBSA?node-id=0-1&t=R3zIVCc39LtNF4No-1' },
        ],
      }
    : sourceProject?.title.trim().toLowerCase() === 'restart'
      ? { ...sourceProject, links: [...(sourceProject.links ?? []).filter((link) => !link.href.includes('friscostyle.com/access-granted')), { label: 'Frisco Style feature', href: 'https://friscostyle.com/access-granted/' }] }
      : sourceProject;
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    if (!project) return;

    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    function handleEscape(event: KeyboardEvent) {
      if (event.key === 'Escape') {
        onClose();
      }
    }

    window.addEventListener('keydown', handleEscape);

    return () => {
      document.body.style.overflow = originalOverflow;
      window.removeEventListener('keydown', handleEscape);
    };
  }, [project, onClose]);

  if (!mounted || !project) {
    return null;
  }

  const videoLink = project.title.toLowerCase() === 'promptly'
    ? project.links?.find((link) => /video|demo/i.test(link.label))
    : undefined;
  const driveId = videoLink?.href.match(/drive\.google\.com\/file\/d\/([^/]+)/)?.[1];
  const videoEmbed = driveId ? `https://drive.google.com/file/d/${driveId}/preview` : undefined;

  return createPortal(
    <div className="project-modal" role="dialog" aria-modal="true">
      <button
        className="modal-backdrop"
        type="button"
        aria-label="Close project modal"
        onClick={onClose}
      />

      <article className="modal-card">
        <button className="modal-close" type="button" onClick={onClose}>
          ×
        </button>

        {project.image ? (
          <div className="modal-image-wrap">
            <img src={project.image} alt={`${project.title} preview`} />
          </div>
        ) : null}

        <div className="modal-content">
          <p className="modal-kicker">{project.category}</p>
          <h2>{project.title}</h2>

          {project.tags && project.tags.length > 0 ? (
            <div className="modal-tags">
              {project.tags.map((tag) => (
                <span key={tag}>{tag}</span>
              ))}
            </div>
          ) : null}

          {project.title.trim().toLowerCase() !== 'halo' && <p className="modal-description">{project.title.toLowerCase() === 'promptly'
            ? 'A sustainability-focused browser extension that helps people write clearer, more efficient AI prompts through real-time feedback and instant revisions.'
            : project.description}</p>}

          {project.title.toLowerCase() === 'promptly' ? (
            <div className="promptly-story">
              <section><p className="promptly-eyebrow">01 / THE PROBLEM</p><h3>Small changes in a prompt. A bigger question about resources.</h3><p>AI interactions require computation. Promptly explores how unnecessary wording and unclear instructions can add friction to an interaction, especially when people use coding agents repeatedly. The goal is to help users communicate their intent more directly, with fewer unnecessary tokens.</p></section>
              <section><p className="promptly-eyebrow">02 / THE APPROACH</p><h3>Improve the prompt while it is being written</h3><p>Rather than ask users to learn a new workflow, Promptly fits into the browser as an extension. It provides feedback as users type, highlights opportunities to improve a prompt, and suggests clearer revisions that preserve the original request.</p></section>
              <section><p className="promptly-eyebrow">03 / A SIMPLE EXAMPLE</p><h3>Keep the intention. Trim the extra wording.</h3>
                <div className="promptly-example"><span>Original</span><p>Can you please tell me the weather forecast for tomorrow? Thank you for your help!</p></div>
                <div className="promptly-example"><span>Revised</span><p>What’s the weather forecast for tomorrow?</p></div>
                <p>The revision keeps the question intact and makes it more concise. The priority is clarity and useful context; shorter wording alone does not establish a fixed energy saving.</p>
              </section>
              <section><p className="promptly-eyebrow">04 / THE EXPERIENCE</p><h3>Helpful feedback without interrupting the task</h3><ul><li>Real-time feedback while typing</li><li>Highlighted prompting issues and improvement opportunities</li><li>Suggested revisions available immediately</li><li>A clean, non-intrusive interface</li><li>A green visual identity that reflects the sustainability focus</li></ul></section>
              <section><p className="promptly-eyebrow">05 / MODEL EXPLORATION</p><h3>Exploring smaller models, closer to the user</h3><p>The technical direction explores Ollama and compact models such as Phi-3-mini to support prompt revision on a user’s own hardware. This considers whether a smaller model can handle a focused task without sending every revision to a large cloud model.</p><p>Local processing still uses energy. Its resource footprint depends on the model, hardware, and workload, so energy and water savings remain something to measure.</p></section>
              <section><p className="promptly-eyebrow">06 / OUTCOME</p><h3>First place at AI4Good</h3><p>Promptly won first place at the AI4Good Hackathon, bringing together prompt optimization, an accessible extension experience, and a sustainability-focused product direction.</p></section>
              <style jsx>{`
                .promptly-story section { margin-top: 30px; }
                .promptly-story h3 { margin: 8px 0 12px; font-size: 22px; line-height: 1.3; }
                .promptly-story p, .promptly-story li { font-size: 15px; line-height: 1.75; }
                .promptly-eyebrow { font-size: 11px !important; letter-spacing: .1em; color: var(--muted); }
                .promptly-example { margin: 14px 0; padding: 18px 20px; border-radius: 14px; background: var(--line); }
                .promptly-example span { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .08em; }
                .promptly-example p { margin: 8px 0 0; }
                .promptly-story ul { padding-left: 20px; }
              `}</style>
            </div>
          ) : /^claude\s*9$/i.test(project.title) ? (
            <div className="claude-story">
              <section><p className="claude-eyebrow">01 / THE PROBLEM</p><h3>A prototype is only the beginning</h3><p>AI tools make it easier to build a prototype, but turning that prototype into a useful product takes more than code. Teams still need to understand their customers, deploy reliably, and decide what to improve after launch.</p></section>
              <section><p className="claude-eyebrow">02 / THE CONCEPT</p><h3>From AI prototype to market-ready product</h3><p>Claude9 proposes an enterprise launch layer that connects market intelligence, deployment, and ongoing optimization. Developed for the Mosaic Case Competition, the concept brings these steps into one product workflow.</p></section>
              <section><p className="claude-eyebrow">03 / MARKET INTELLIGENCE</p><h3>Know who you’re building for</h3><p>The proposed intelligence layer helps teams define their ideal customer profile, develop a go-to-market strategy, and identify gaps in competing products. Traffic and engagement insights would help teams understand what resonates after launch.</p></section>
              <figure className="claude-figure"><img src={claudeFigures[0].src} alt={claudeFigures[0].alt} loading="lazy" /></figure>
              <section><p className="claude-eyebrow">04 / DEPLOY &amp; HOST</p><h3>Make shipping part of the workflow</h3><p>The deployment concept combines one-click AWS deployment, Docker packaging for local development, and Kubernetes autoscaling. The aim is to reduce the operational steps between a working prototype and a deployed product.</p></section>
              <figure className="claude-figure"><img src={claudeFigures[1].src} alt={claudeFigures[1].alt} loading="lazy" /></figure>
              <section><p className="claude-eyebrow">05 / OPTIMIZATION</p><h3>Learn from how the product is used</h3><p>Claude9’s proposed feedback loop uses product data to suggest revisions, log changes, and measure their effects. This connects launch decisions to an ongoing cycle of testing and improvement.</p></section>
              <figure className="claude-figure"><img src={claudeFigures[2].src} alt={claudeFigures[2].alt} loading="lazy" /></figure>
              <section><p className="claude-eyebrow">06 / FUTURE VISION</p><h3>Describe. Review. Build.</h3><p>A future hardware direction extends the concept beyond software: describe an idea, review the proposed design, and move toward a physical prototype. The five-year roadmap outlines a progression from prompt-to-prototype tools and user validation to schematics, bills of materials, firmware support, and connected development workflows, followed by supplier matching and manufacturing guidance.</p><p>These deployment, automation, and hardware capabilities describe the proposed product direction and roadmap.</p></section>
              <figure className="claude-figure"><img src={claudeFigures[3].src} alt={claudeFigures[3].alt} loading="lazy" /></figure>
              <figure className="claude-figure"><img src={claudeFigures[4].src} alt={claudeFigures[4].alt} loading="lazy" /></figure>
              <section><p className="claude-eyebrow">07 / OUTCOME</p><h3>Funded at the Mosaic Case Competition</h3><p>The project received funding at the Mosaic Case Competition for its product direction connecting AI prototyping with launch and go-to-market support.</p></section>
              <style jsx>{`
                .claude-story section { margin-top: 30px; }
                .claude-figure { margin: 22px 0 30px; }
                .claude-figure img { display: block; width: 100%; height: auto; border-radius: 14px; }
                .claude-story h3 { margin: 8px 0 12px; font-size: 22px; line-height: 1.3; }
                .claude-story p { font-size: 15px; line-height: 1.75; }
                .claude-eyebrow { font-size: 11px !important; letter-spacing: .1em; color: var(--muted); }
              `}</style>
            </div>
          ) : project.title.trim().toLowerCase() !== 'rewind' && project.process && project.process.trim() !== project.description.trim() ? <div className="modal-process"><p>{project.process}</p></div> : null}

          {project.title.trim().toLowerCase() === 'halo' && (
            <section aria-label="Halo presentation" style={{ marginTop: 32, marginBottom: 28 }}>
              <h3 style={{ margin: '0 0 14px', fontSize: 22 }}>Explore the presentation</h3>
              <div style={{ position: 'relative', width: '100%', aspectRatio: '16 / 9', overflow: 'hidden', borderRadius: 16, background: '#f2eee8' }}>
                <iframe
                  src="https://www.canva.com/design/DAG3t5r-UzM/hIiEIV79haXE_MMhyg2fCw/view?embed"
                  title="Halo presentation"
                  allow="fullscreen"
                  allowFullScreen
                  loading="lazy"
                  style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', border: 0 }}
                />
              </div>
            </section>
          )}

          {['ai communication assistant', 'glamor lab'].includes(project.title.trim().toLowerCase()) && (
            <div className="communication-story">
              <section><p className="communication-eyebrow">CURRENT WORK / PATIENT USE</p><h3>Preparing for real patient use</h3><p>We’re refining the prototype with an ENT surgeon at the Keck School of Medicine for upcoming use with patients undergoing laryngectomy. Patients will test the app and provide feedback to help us improve the experience around their communication needs.</p></section>
              <section><p className="communication-eyebrow">01 / RECORD &amp; REVIEW</p><h3>Begin with a silent phrase</h3><p>The prototype guides the patient from the home screen into camera recording, then gives them a chance to review the clip before continuing.</p>
                <div className="communication-grid">{communicationFigures.slice(0, 3).map((figure) => <figure key={figure.caption}><img src={figure.src} alt={figure.caption} loading="lazy" /><figcaption>{figure.caption}</figcaption></figure>)}</div>
              </section>
              <section><p className="communication-eyebrow">02 / CONFIRM &amp; SPEAK</p><h3>Keep the patient in control of the message</h3><p>Suggested phrases can be selected, edited, and confirmed before voice playback. The flow lets the patient check the wording before communicating it aloud.</p>
                <div className="communication-grid">{communicationFigures.slice(3, 6).map((figure) => <figure key={figure.caption}><img src={figure.src} alt={figure.caption} loading="lazy" /><figcaption>{figure.caption}</figcaption></figure>)}</div>
              </section>
              <section><p className="communication-eyebrow">03 / PERSONALIZE &amp; REFINE</p><h3>Support the next conversation</h3><p>Feedback captures how the interaction went, history keeps previous phrases available, and voice setup explores ways to personalize speech output. These screens show the prototype experience being developed to support patient validation.</p>
                <div className="communication-grid">{communicationFigures.slice(6, 9).map((figure) => <figure key={figure.caption}><img src={figure.src} alt={figure.caption} loading="lazy" /><figcaption>{figure.caption}</figcaption></figure>)}</div>
              </section>
              <style jsx>{`
                .communication-story section { margin-top: 32px; }
                .communication-eyebrow { font-size: 11px; letter-spacing: .1em; color: var(--muted); }
                .communication-story h3 { margin: 8px 0 12px; font-size: 22px; line-height: 1.3; }
                .communication-story p { line-height: 1.75; }
                .communication-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; margin-top: 24px; }
                .communication-grid figure { margin: 0; min-width: 0; }
                .communication-grid img { display: block; width: 100%; height: auto; border-radius: 16px; }
                .communication-grid figcaption { margin-top: 12px; font-size: 13px; line-height: 1.5; text-align: center; color: var(--muted); }
                @media (max-width: 540px) { .communication-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; } }
              `}</style>
            </div>
          )}

          {project.title.trim().toLowerCase() === 'restart' && (
            <section aria-label="Restart press features" style={{ marginTop: 32 }}>
              {restartFigures.map((figure) => (
                <figure key={figure.alt} style={{ margin: '0 0 24px' }}>
                  {figure.alt.startsWith('Access Granted') ? (
                    <a href="https://friscostyle.com/access-granted/" target="_blank" rel="noopener noreferrer" aria-label="Read Access Granted in Frisco Style">
                      <img src={figure.src} alt={figure.alt} loading="lazy" style={{ display: 'block', width: '100%', height: 'auto', borderRadius: 14 }} />
                    </a>
                  ) : (
                    <img src={figure.src} alt={figure.alt} loading="lazy" style={{ display: 'block', width: '100%', height: 'auto', borderRadius: 14 }} />
                  )}
                </figure>
              ))}
            </section>
          )}

          {/^claude\s*9$/i.test(project.title) && (
            <>
            <section aria-label="Claude9 slide 28 demo" style={{ marginTop: 32, marginBottom: 28 }}>
              <h3 style={{ margin: '0 0 14px', fontSize: 22 }}>Watch the demo</h3>
              <div style={{ position: 'relative', width: '100%', aspectRatio: '16 / 10', minHeight: 320, overflow: 'hidden', borderRadius: 16, background: '#f2eee8' }}>
                <iframe
                  src={`https://www.figma.com/embed?embed_host=share&url=${encodeURIComponent('https://www.figma.com/proto/nKxWurMXCINdBnZ4GyuGoo/Claude9-Mosaic?node-id=44-344&scaling=contain&content-scaling=fixed&page-id=0%3A1&starting-point-node-id=44%3A344&show-proto-sidebar=0')}`}
                  title="Claude9 video demo — slide 28"
                  allow="autoplay; fullscreen; picture-in-picture"
                  allowFullScreen
                  loading="lazy"
                  style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', border: 0 }}
                />
              </div>
            </section>
            <section aria-label="Claude9 presentation" style={{ marginTop: 32, marginBottom: 28 }}>
              <h3 style={{ margin: '0 0 14px', fontSize: 22 }}>Explore the presentation</h3>
              <div style={{ position: 'relative', width: '100%', aspectRatio: '16 / 10', minHeight: 320, overflow: 'hidden', borderRadius: 16, background: '#f2eee8' }}>
                <iframe
                  src={`https://www.figma.com/embed?embed_host=share&url=${encodeURIComponent('https://www.figma.com/proto/nKxWurMXCINdBnZ4GyuGoo/Claude9-MBSA?node-id=0-1&scaling=contain&content-scaling=fixed')}`}
                  title="Claude9 interactive presentation"
                  allow="fullscreen"
                  allowFullScreen
                  loading="lazy"
                  style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', border: 0 }}
                />
              </div>
            </section>
            </>
          )}

          {videoEmbed && (
            <section aria-label="Video demonstration" style={{ marginTop: 28, marginBottom: 28 }}>
              <h3 style={{ margin: '0 0 14px', fontSize: 20 }}>Watch the demo</h3>
              <div style={{ position: 'relative', width: '100%', aspectRatio: '16 / 9', overflow: 'hidden', borderRadius: 16, background: '#111' }}>
                <iframe src={videoEmbed} title={`${project.title} video demo`} allow="autoplay; fullscreen; picture-in-picture" allowFullScreen loading="lazy" style={{ position: 'absolute', top: 0, left: '-48px', width: 'calc(100% + 96px)', height: '100%', border: 0 }} />
              </div>
            </section>
          )}

          {project.links && project.links.length > 0 ? (
            <div className="modal-actions">
              {project.links.map((link) => (
                <a
                  className="modal-link"
                  href={link.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  key={`${link.label}-${link.href}`}
                >
                  {link.label} →
                </a>
              ))}
            </div>
          ) : null}
        </div>
      </article>
    </div>,
    document.body
  );
}
